// signatures and constants). It differs in scanning, with the phone's radio (megler.Bluetooth): while any of the app's scans
// runs the radio listens, actively (asking for scan responses, as Android's scans do) unless every scan is opportunistic,
// and each advertisement heard (its record with its scan response's after it) goes to every scan whose filters it passes
// -- all of them when a scan has none -- on the main thread, as Android's: onScanResult for every match (or the first of a
// device's alone, CALLBACK_TYPE_FIRST_MATCH), or onBatchScanResults every report delay. A callback started twice hears
// SCAN_FAILED_ALREADY_STARTED; a scan the radio cannot run hears its code; the radio turned off ends every scan, unheard,
// as Android ends them with the adapter. An app that targets Android 12 needs BLUETOOTH_SCAN (SecurityException without);
// an older one hears results even without the location, which Android 10 and later would ask of it (located).
// Scans that hand their results to a PendingIntent are not there (SCAN_FAILED_FEATURE_UNSUPPORTED).
package android.bluetooth.le;

import android.bluetooth.BluetoothAdapter;
import android.bluetooth.BluetoothDevice;
import android.os.Handler;
import android.os.Looper;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;

@SuppressWarnings({"unchecked", "rawtypes", "deprecation"})
public final class BluetoothLeScanner {
    private static final String TAG = "BluetoothLeScanner";
    private static final Handler sMain = new Handler(Looper.getMainLooper());
    private static final ArrayList<Scan> sScans = new ArrayList<>();
    private static boolean sSaidNoLocation;

    /** A scan of the app's: its callback, its filters and settings, and what it has been given. */
    private static final class Scan {
        final ScanCallback callback;
        final List<ScanFilter> filters;
        final ScanSettings settings;
        final boolean located;
        final HashSet<Long> matched = new HashSet<>();
        final ArrayList<ScanResult> batch = new ArrayList<>();
        boolean flushPosted;

        Scan(ScanCallback callback, List<ScanFilter> filters, ScanSettings settings, boolean located) {
            this.callback = callback;
            this.filters = filters != null ? new ArrayList<>(filters) : new ArrayList<ScanFilter>();
            this.settings = settings;
            this.located = located;
        }

        boolean passes(ScanResult r) {
            if (filters.isEmpty()) return true;
            for (ScanFilter f : filters)
                if (f == null || f.matches(r)) return true;
            return false;
        }
    }

    public BluetoothLeScanner(BluetoothAdapter adapter) {}
    BluetoothLeScanner() { this((BluetoothAdapter) null); }

    public void startScan(ScanCallback callback) { startScan(null, new ScanSettings.Builder().build(), callback); }

    public void startScan(List<ScanFilter> filters, ScanSettings settings, ScanCallback callback) {
        megler.Bluetooth.enforce("android.permission.BLUETOOTH_SCAN", "BluetoothLeScanner.startScan");
        if (callback == null) throw new IllegalArgumentException("callback is null");
        if (settings == null) throw new IllegalArgumentException("settings is null");
        if (megler.Bluetooth.state() != megler.Bluetooth.RADIO_ON) throw new IllegalStateException("BT Adapter is not turned ON");
        final ScanCallback cb = callback;
        synchronized (sScans) {
            for (Scan s : sScans)
                if (s.callback == callback) {
                    sMain.post(() -> cb.onScanFailed(ScanCallback.SCAN_FAILED_ALREADY_STARTED));
                    return;
                }
            sScans.add(new Scan(callback, filters, settings, located()));
        }
        radio();
    }

    public int startScan(List<ScanFilter> filters, ScanSettings settings, android.app.PendingIntent callbackIntent) { return ScanCallback.SCAN_FAILED_FEATURE_UNSUPPORTED; }

    public void stopScan(ScanCallback callback) {
        boolean had = false;
        synchronized (sScans) {
            for (int i = sScans.size() - 1; i >= 0; i--)
                if (sScans.get(i).callback == callback) {
                    sScans.remove(i);
                    had = true;
                }
        }
        if (had) radio();
    }
    public void stopScan(android.app.PendingIntent callbackIntent) {}

    /** What waits for a scan's report delay, given now. */
    public void flushPendingScanResults(ScanCallback callback) {
        Scan scan = null;
        synchronized (sScans) {
            for (Scan s : sScans)
                if (s.callback == callback) scan = s;
        }
        if (scan != null) flush(scan);
    }

    /**
     * Whether the app's scans hear results. Android 10 and later give an app of a target before Android 12 none without the
     * location granted; Megler gives them anyway -- the location is Windows' to grant, and a phone whose location is off
     * would hear no radio -- and says once that the app scans without it.
     */
    private static boolean located() {
        if (megler.Manifest.targetSdk >= 31 || sSaidNoLocation) return true;
        if (megler.Permissions.check("android.permission.ACCESS_FINE_LOCATION") != megler.Permissions.GRANTED
            && megler.Permissions.check("android.permission.ACCESS_COARSE_LOCATION") != megler.Permissions.GRANTED) {
            sSaidNoLocation = true;
            android.util.Log.i(TAG, "the app scans without the location, which Android would ask of an app of its target: its results are given all the same");
        }
        return true;
    }

    /** The radio's scan as the scans want it: active while any is not opportunistic, passive for opportunistic ones alone. */
    private static void radio() {
        int mode = megler.Bluetooth.SCAN_OFF;
        synchronized (sScans) {
            for (Scan s : sScans)
                mode = Math.max(mode, s.settings.getScanMode() == ScanSettings.SCAN_MODE_OPPORTUNISTIC ? megler.Bluetooth.SCAN_PASSIVE : megler.Bluetooth.SCAN_ACTIVE);
        }
        megler.Bluetooth.scan(mode);
    }

    private static void flush(final Scan scan) {
        final ArrayList<ScanResult> list;
        synchronized (sScans) {
            scan.flushPosted = false;
            if (scan.batch.isEmpty()) return;
            list = new ArrayList<>(scan.batch);
            scan.batch.clear();
        }
        sMain.post(() -> scan.callback.onBatchScanResults(list));
    }

    /** An advertisement heard (megler.Bluetooth's thread): to every scan whose filters it passes, on the main thread. */
    public static void meglerHeard(long address, int type, int rssi, boolean connectable, byte[] advertisement, long timeNanos) {
        ArrayList<Scan> to = new ArrayList<>();
        synchronized (sScans) { to.addAll(sScans); }
        if (to.isEmpty()) return;
        BluetoothDevice device = BluetoothDevice.meglerOf(address, type == megler.Bluetooth.ADDRESS_RANDOM ? BluetoothDevice.ADDRESS_TYPE_RANDOM : BluetoothDevice.ADDRESS_TYPE_PUBLIC);
        ScanRecord record = ScanRecord.parseFromBytes(advertisement != null ? advertisement : new byte[0]);
        int eventType = (ScanResult.DATA_COMPLETE << 5) | ScanResult.ET_LEGACY_MASK | (connectable ? ScanResult.ET_CONNECTABLE_MASK | ScanResult.ET_SCANNABLE_MASK : 0);
        final ScanResult result = new ScanResult(device, eventType, BluetoothDevice.PHY_LE_1M, ScanResult.PHY_UNUSED, ScanResult.SID_NOT_PRESENT,
                                                 ScanResult.TX_POWER_NOT_PRESENT, rssi, ScanResult.PERIODIC_INTERVAL_NOT_PRESENT, record, timeNanos);
        for (final Scan scan : to) {
            if (!scan.located || !scan.passes(result)) continue;
            int callbackType = scan.settings.getCallbackType();
            if ((callbackType & ScanSettings.CALLBACK_TYPE_FIRST_MATCH) != 0) {
                synchronized (sScans) {
                    if (!scan.matched.add(address)) continue;
                }
            } else if (callbackType == ScanSettings.CALLBACK_TYPE_MATCH_LOST) {
                continue;
            }
            long delay = scan.settings.getReportDelayMillis();
            if (delay > 0 && (callbackType & ScanSettings.CALLBACK_TYPE_FIRST_MATCH) == 0) {
                boolean post;
                synchronized (sScans) {
                    scan.batch.add(result);
                    post = !scan.flushPosted;
                    scan.flushPosted = true;
                }
                if (post) sMain.postDelayed(() -> flush(scan), delay);
                continue;
            }
            final int type0 = (callbackType & ScanSettings.CALLBACK_TYPE_FIRST_MATCH) != 0 ? ScanSettings.CALLBACK_TYPE_FIRST_MATCH : ScanSettings.CALLBACK_TYPE_ALL_MATCHES;
            sMain.post(() -> {
                boolean still;
                synchronized (sScans) { still = sScans.contains(scan); }
                if (still) scan.callback.onScanResult(type0, result);
            });
        }
    }

    /** The radio could not scan, or stopped (megler.Bluetooth's thread): every scan hears the code and ends. */
    public static void meglerFailed(final int code) {
        ArrayList<Scan> was;
        synchronized (sScans) {
            was = new ArrayList<>(sScans);
            sScans.clear();
        }
        for (final Scan s : was) sMain.post(() -> s.callback.onScanFailed(code));
        radio();
    }

    /** The radio turned off: the scans end, unheard, as Android's end with the adapter. */
    public static void meglerRadioOff() {
        synchronized (sScans) { sScans.clear(); }
    }
    public static final java.lang.String EXTRA_CALLBACK_TYPE = "android.bluetooth.le.extra.CALLBACK_TYPE";
    public static final java.lang.String EXTRA_ERROR_CODE = "android.bluetooth.le.extra.ERROR_CODE";
    public static final java.lang.String EXTRA_LIST_SCAN_RESULT = "android.bluetooth.le.extra.LIST_SCAN_RESULT";
    public void cleanup() {}
    public void startScanFromSource(android.os.WorkSource p0, android.bluetooth.le.ScanCallback p1) {}
    public void startScanFromSource(java.util.List p0, android.bluetooth.le.ScanSettings p1, android.os.WorkSource p2, android.bluetooth.le.ScanCallback p3) {}
    public void startTruncatedScan(java.util.List p0, android.bluetooth.le.ScanSettings p1, android.bluetooth.le.ScanCallback p2) {}
}
